/**
 * wowacool Worker entry.
 *
 * Phase 1 is deployable as a health surface. Job creation, copy, images,
 * review, and export still run through the local CLI (`npm run cli`) until
 * D1, R2, and Queues exist. This module does not call Xiaohongshu, OpenRouter,
 * or any image API, and it does not publish notes.
 *
 * `Env` comes from `worker-configuration.d.ts`, generated by `wrangler types`
 * during `npm run build`. Do not hand-write binding types in this file.
 */
import { PROJECT_NAME } from "../constants.js";

const ROUTES = [
  "GET /health",
  "POST /catalog/refresh",
  "GET /quota",
  "POST /jobs",
  "GET /jobs/:id",
  "POST /jobs/:id/draft",
  "POST /jobs/:id/images",
  "POST /jobs/:id/review",
  "POST /jobs/:id/export",
] as const;

const PLANNED = new Set<string>([
  "POST /catalog/refresh",
  "GET /quota",
  "POST /jobs",
  "GET /jobs/:id",
  "POST /jobs/:id/draft",
  "POST /jobs/:id/images",
  "POST /jobs/:id/review",
  "POST /jobs/:id/export",
]);

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    console.log(
      JSON.stringify({
        message: "incoming request",
        method: request.method,
        path: url.pathname,
      }),
    );

    if (request.method === "GET" && (url.pathname === "/health" || url.pathname === "/")) {
      return json({
        ok: true,
        service: PROJECT_NAME,
        phase: env.PHASE ?? "1",
        mode: "health",
        imageProvider: env.IMAGE_PROVIDER ?? "mock",
        copy: "openrouter-free-text-only",
        writeNotes: "planned",
        humanReviewRequired: true,
        routes: ROUTES,
      });
    }

    const routeKey = matchPlannedRoute(request.method, url.pathname);
    if (routeKey) {
      console.log(
        JSON.stringify({
          message: "planned route is not bound yet",
          method: request.method,
          path: url.pathname,
          route: routeKey,
        }),
      );
      return json(
        {
          ok: false,
          error:
            "wowacool phase 1 exports a reviewable package from the local CLI. This Worker route stays unimplemented until D1, R2, and Queues are created. It does not publish notes.",
          route: routeKey,
          routes: ROUTES,
        },
        501,
      );
    }

    console.error(
      JSON.stringify({
        message: "unknown route",
        method: request.method,
        path: url.pathname,
      }),
    );
    return json({ ok: false, error: "not found", routes: ROUTES }, 404);
  },
} satisfies ExportedHandler<Env>;

function matchPlannedRoute(method: string, pathname: string): string | null {
  const exact = `${method} ${pathname}`;
  if (PLANNED.has(exact)) return exact;
  if (method === "GET" && /^\/jobs\/[^/]+$/.test(pathname)) return "GET /jobs/:id";
  const action = pathname.match(/^\/jobs\/[^/]+\/(draft|images|review|export)$/);
  if (method === "POST" && action) return `POST /jobs/:id/${action[1]}`;
  return null;
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body, null, 2), {
    status,
    headers: { "content-type": "application/json; charset=utf-8" },
  });
}
